<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { CreateTask, CreateUnit, ExportData, GetDefaultUnitID, ImportData, ListTasks, ListUnits, SetDefaultUnit, UpdateTask, UpdateTaskStatus, UpdateUnit } from '../wailsjs/go/main/App'
type Status='in_progress'|'completed'|'cancelled'; type Kind='main'|'branch'|'child'; type TaskType='code'|'document'|'support'
type Task={id:string;name:string;kind:Kind;parentId:string;issuer:string;unit:string;publishDate:string;dueDate:string;taskType:TaskType;status:Status;deliverable:string;summary:string;completedAt:string;createdAt:string;updatedAt:string}; type Unit={id:string;name:string}
const tasks=ref<Task[]>([]),units=ref<Unit[]>([]),defaultUnitID=ref(''),selected=ref<Task|null>(null),showCreate=ref(false),showUnits=ref(false),showAbout=ref(false),newUnit=ref(''),message=ref(''),query=ref(''),status=ref('all'),kindFilter=ref('all'),type=ref('all'),viewMode=ref<'list'|'calendar'>('list'),calendarMonth=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1))
const today=()=>new Date().toISOString().slice(0,10); const draft=reactive({name:'',kind:'main' as Kind,parentId:'',issuer:'',unit:'',publishDate:today(),dueDate:today(),taskType:'code' as TaskType})
const text:Record<Status,string>={in_progress:'进行中',completed:'已完成',cancelled:'已取消'};const kindText:Record<Kind,string>={main:'主线任务',branch:'支线任务',child:'子任务'}
const mains=computed(()=>tasks.value.filter(t=>t.kind==='main'));const filtered=computed(()=>tasks.value.filter(t=>(status.value==='all'||t.status===status.value)&&(kindFilter.value==='all'||t.kind===kindFilter.value)&&(type.value==='all'||t.taskType===type.value)&&`${t.name} ${t.unit} ${t.issuer}`.toLowerCase().includes(query.value.toLowerCase())))
const visible=(t:Task)=>filtered.value.some(x=>x.id===t.id)||tasks.value.some(x=>x.kind==='child'&&x.parentId===t.id&&filtered.value.some(y=>y.id===x.id));const overdue=(t:Task)=>t.status==='in_progress'&&!!t.dueDate&&t.dueDate<today()
const dateKey=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const monthTitle=computed(()=>`${calendarMonth.value.getFullYear()} 年 ${calendarMonth.value.getMonth()+1} 月`)
const calendarDays=computed(()=>{const first=new Date(calendarMonth.value.getFullYear(),calendarMonth.value.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return{date:d,key:dateKey(d),current:d.getMonth()===calendarMonth.value.getMonth()}})})
function calendarTasks(key:string){const now=today();return filtered.value.filter(t=>{if(!t.publishDate)return false;const end=t.status==='in_progress'?(t.dueDate&&t.dueDate<now?t.dueDate:now):(t.completedAt||t.dueDate||t.publishDate);return key>=t.publishDate&&key<=end})}function previousMonth(){calendarMonth.value=new Date(calendarMonth.value.getFullYear(),calendarMonth.value.getMonth()-1,1)}function nextMonth(){calendarMonth.value=new Date(calendarMonth.value.getFullYear(),calendarMonth.value.getMonth()+1,1)}
function calendarTaskClass(task:Task,key:string){const now=today(),end=task.status==='in_progress'?(task.dueDate&&task.dueDate<now?task.dueDate:now):(task.completedAt||task.dueDate||task.publishDate);return{start:key===task.publishDate||key.endsWith('-01'),end:key===end||new Date(`${key}T00:00:00`).getDay()===6}}
const calendarTracks=computed(()=>{const assigned=new Map<string,number>(),tracks:string[][]=[];const keys=calendarDays.value.map(d=>d.key);const ranges=filtered.value.filter(t=>t.publishDate).map(t=>{const now=today(),end=t.status==='in_progress'?(t.dueDate&&t.dueDate<now?t.dueDate:now):(t.completedAt||t.dueDate||t.publishDate);return{task:t,start:keys.findIndex(k=>k>=t.publishDate),end:keys.length-1-keys.slice().reverse().findIndex(k=>k<=end)}}).filter(x=>x.start>=0&&x.end>=x.start).sort((a,b)=>a.start-b.start);for(const item of ranges){let track=0;while(tracks[track]?.slice(item.start,item.end+1).some(Boolean))track++;tracks[track]??=[];for(let i=item.start;i<=item.end;i++)tracks[track][i]=item.task.id;assigned.set(item.task.id,track)}return assigned})
function taskTrack(task:Task){return calendarTracks.value.get(task.id)??0}
async function refresh(){const [ts,us,d]=await Promise.all([ListTasks(),ListUnits(),GetDefaultUnitID()]);tasks.value=(ts??[])as Task[];units.value=(us??[])as Unit[];defaultUnitID.value=d||'';selected.value=selected.value?tasks.value.find(t=>t.id===selected.value?.id)||null:tasks.value[0]||null}
function openCreate(){if(!units.value.length){showUnits.value=true;message.value='请先创建一个单位';return}draft.unit=units.value.find(u=>u.id===defaultUnitID.value)?.name||units.value[0].name;showCreate.value=true}function setKind(o:{kind:Kind,parentId:string},v:Kind){o.kind=v;o.parentId=''}function setSelf(o:{issuer:string},e:Event){o.issuer=(e.target as HTMLInputElement).checked?'本人':''}function setUnlimited(o:{dueDate:string},e:Event){o.dueDate=(e.target as HTMLInputElement).checked?'':today()}
async function create(){try{const t=await CreateTask({...draft})as Task;showCreate.value=false;Object.assign(draft,{name:'',kind:'main',parentId:'',issuer:'',unit:'',publishDate:today(),dueDate:today(),taskType:'code'});await refresh();selected.value=t;message.value='任务已创建'}catch(e){message.value=String(e)}}async function save(){if(!selected.value)return;try{await UpdateTask(selected.value);await refresh();message.value='任务已保存'}catch(e){message.value=String(e)}}async function changeStatus(s:Status){if(!selected.value)return;await UpdateTaskStatus(selected.value.id,s);await refresh()}async function addUnit(){try{await CreateUnit(newUnit.value);newUnit.value='';await refresh()}catch(e){message.value=String(e)}}async function rename(u:Unit){const n=prompt('修改单位名称',u.name);if(n!==null){try{await UpdateUnit(u.id,n);await refresh()}catch(e){message.value=String(e)}}}async function setDefault(id:string){await SetDefaultUnit(id);await refresh()}async function exportData(){await ExportData()}async function importData(){await ImportData();await refresh()}onMounted(()=>refresh().catch(e=>message.value=String(e)))
</script>
<template><main class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✓</span><div><b>Task Manager</b><small>工作任务管理器</small></div></div><p class="side-title">任务概览</p><button v-for="s in ['all','in_progress','completed','cancelled']" class="nav-item" :class="{active:status===s}" @click="status=s"><span>{{s==='all'?'全部任务':text[s as Status]}}</span><em>{{s==='all'?tasks.length:tasks.filter(t=>t.status===s).length}}</em></button><button class="nav-item" @click="showUnits=true"><span>单位管理</span><em>{{units.length}}</em></button><button class="nav-item about-button" @click="showAbout=true"><span>ⓘ 关于</span></button></aside><section class="workspace"><header><div><p class="eyebrow">工作空间</p><div class="title-line"><h1>我的任务</h1><div class="view-switch"><button :class="{active:viewMode==='list'}" @click="viewMode='list'">列表</button><button :class="{active:viewMode==='calendar'}" @click="viewMode='calendar'">日历</button></div></div></div><div class="actions"><button @click="importData">导入 JSON</button><button @click="exportData">导出 JSON</button><button class="primary" @click="openCreate">＋ 新建任务</button></div></header><div class="toolbar"><input v-model="query" placeholder="搜索任务名、下发人或单位"><select v-model="kindFilter"><option value="all">全部层级</option><option v-for="(_,k) in kindText" :value="k">{{kindText[k as Kind]}}</option></select><select v-model="type"><option value="all">全部类型</option><option value="code">代码</option><option value="document">文档</option><option value="support">支持</option></select></div><div v-if="viewMode==='list'" class="task-list"><template v-for="top in tasks.filter(t=>(t.kind==='main'||t.kind==='branch')&&visible(t))" :key="top.id"><button class="task-row" :class="{completed:top.status==='completed'}" @click="selected=top"><span>{{top.kind==='main'?'◆':'◇'}}</span><span class="task-name">{{top.name}}<small>{{kindText[top.kind]}} · {{top.unit}} · {{top.issuer}}</small></span><span class="date">{{top.status==='completed'?(top.completedAt||'已完成'):top.dueDate||'无期限'}}</span><span class="badge" :class="top.status">{{text[top.status]}}</span></button><button v-for="child in tasks.filter(t=>t.kind==='child'&&t.parentId===top.id&&filtered.some(x=>x.id===t.id))" class="task-row child" :class="{completed:child.status==='completed'}" @click="selected=child"><span>↳</span><span class="task-name">{{child.name}}<small>子任务 · {{child.unit}} · {{child.issuer}}</small></span><span class="date">{{child.status==='completed'?(child.completedAt||'已完成'):child.dueDate||'无期限'}}</span><span class="badge" :class="child.status">{{text[child.status]}}</span></button></template><div v-if="!filtered.length" class="empty">暂无任务。</div></div><div v-else class="calendar-view"><div class="calendar-head"><button @click="previousMonth">‹</button><strong>{{monthTitle}}</strong><button @click="nextMonth">›</button></div><div class="calendar-scroll"><div class="calendar-week"><span v-for="w in ['日','一','二','三','四','五','六']">周{{w}}</span></div><div class="calendar-grid"><div v-for="day in calendarDays" :key="day.key" class="calendar-cell" :class="{muted:!day.current,today:day.key===today()}"><b>{{day.date.getDate()}}</b><button v-for="task in calendarTasks(day.key)" :key="task.id" class="calendar-task" :class="[task.status,calendarTaskClass(task,day.key)]" :style="{gridRow:taskTrack(task)+2}" @click="selected=task"><span>{{task.name}}</span></button></div></div></div></div></section><aside v-if="selected" class="details"><div class="details-heading"><div><p class="eyebrow">任务详情（可编辑）</p><input v-model="selected.name"></div><span class="badge" :class="selected.status">{{text[selected.status]}}</span></div><div class="status-buttons"><button v-for="s in ['in_progress','completed','cancelled']" :class="{chosen:selected.status===s}" @click="changeStatus(s as Status)">{{text[s as Status]}}</button></div><div class="fields"><label>单位<select v-model="selected.unit"><option v-for="u in units" :value="u.name">{{u.name}}</option></select></label><label>层级<select :value="selected.kind" @change="setKind(selected!,($event.target as HTMLSelectElement).value as Kind)"><option v-for="(_,k) in kindText" :value="k">{{kindText[k as Kind]}}</option></select></label><label v-if="selected.kind==='child'">所属主线<select v-model="selected.parentId"><option value="">请选择</option><option v-for="t in mains" :value="t.id">{{t.name}}</option></select></label><label>下发人<input v-model="selected.issuer" :disabled="selected.issuer==='本人'"><span class="inline-toggle"><input type="checkbox" :checked="selected.issuer==='本人'" @change="setSelf(selected!,$event)"><b>本人</b><i>自动填充并锁定</i></span></label><label>发布日期<input v-model="selected.publishDate" type="date"></label><label>截止日期<input v-model="selected.dueDate" type="date" :disabled="!selected.dueDate"><span class="no-deadline"><input type="checkbox" :checked="!selected.dueDate" @change="setUnlimited(selected!,$event)"><b>无期限</b><i>不设置截止日期</i></span></label><label v-if="selected.status==='completed'">完成日期<input v-model="selected.completedAt" type="date"></label></div><label>产出物<textarea v-model="selected.deliverable"/></label><label>总结<textarea v-model="selected.summary"/></label><button class="primary save" @click="save">保存全部修改</button></aside><aside v-else class="details empty">选择一项任务</aside><div v-if="showCreate" class="modal-backdrop"><form class="modal" @submit.prevent="create"><div class="modal-title"><h2>创建任务</h2><button class="close" type="button" @click="showCreate=false">×</button></div><div class="form-grid"><label>单位<select v-model="draft.unit" required><option v-for="u in units" :value="u.name">{{u.name}}</option></select></label><label>任务层级<select :value="draft.kind" @change="setKind(draft,($event.target as HTMLSelectElement).value as Kind)"><option v-for="(_,k) in kindText" :value="k">{{kindText[k as Kind]}}</option></select></label><label>任务名<input v-model="draft.name" required></label><label>下发人<input v-model="draft.issuer" required :disabled="draft.issuer==='本人'"><span class="inline-toggle"><input type="checkbox" :checked="draft.issuer==='本人'" @change="setSelf(draft,$event)"><b>本人</b><i>自动填充并锁定</i></span></label><label v-if="draft.kind==='child'">所属主线<select v-model="draft.parentId" required><option value="">请选择</option><option v-for="t in mains" :value="t.id">{{t.name}}</option></select></label><label>发布日期<input v-model="draft.publishDate" type="date" required></label><label>截止日期<input v-model="draft.dueDate" type="date" :disabled="!draft.dueDate"><span class="no-deadline"><input type="checkbox" :checked="!draft.dueDate" @change="setUnlimited(draft,$event)"><b>无期限</b><i>不设置截止日期</i></span></label><label>任务类型<select v-model="draft.taskType"><option value="code">代码</option><option value="document">文档</option><option value="support">支持</option></select></label></div><div class="actions"><button type="button" @click="showCreate=false">取消</button><button class="primary">创建任务</button></div></form></div><div v-if="showUnits" class="modal-backdrop"><div class="modal"><div class="modal-title"><h2>单位列表</h2><button class="close" @click="showUnits=false">×</button></div><form class="unit-add" @submit.prevent="addUnit"><input v-model="newUnit" placeholder="输入单位名称"><button class="primary">新增单位</button></form><div class="unit-list"><div v-for="u in units" class="unit-row"><span>{{u.name}}</span><em v-if="u.id===defaultUnitID">默认单位</em><button @click="setDefault(u.id)">设为默认</button><button @click="rename(u)">修改</button></div></div></div></div><button v-if="message" class="toast" @click="message=''">{{message}}</button><div v-if="showAbout" class="modal-backdrop"><div class="modal about-modal"><div class="modal-title"><h2>关于</h2><button class="close" @click="showAbout=false">×</button></div><div class="about-grid"><div><small>程序名</small><strong>Task Manager | 工作任务管理器</strong></div><div><small>版本号</small><strong>alpha</strong></div><div><small>作者</small><strong>李正浩</strong></div></div><div class="actions"><button class="primary" @click="showAbout=false">关闭</button></div></div></div></main></template>
